+    #[test]
+    fn kv_residency_long_lifetimes() {
+        use crate::protocol::stats::KvCacheEvictionEvent;
+
+        let metrics = Metrics::new();
+        let handles = super::resolve_scheduler_stats_handles(&metrics.scheduler, "model", 0);
